Sure! Here's the complete Python implementation of the K-Means algorithm with comments explaining each step:

```
import math
import numpy as np

class KMeans:
    def __init__(self, k):
        self.k = k
        self.centroids = {}
        self.classes = {}

    # Euclidean distance between two points
    def distance(self, pt1, pt2):
        return math.sqrt((pt1[0] - pt2[0])**2 + (pt1[1] - pt2[1])**2)

    def fit(self, data):
        # Initialize the centroids
        for i in range(self.k):
            self.centroids[i] = data[i]

        # Repeat until convergence
        for _ in range(10):
            # Initialize the classes
            for i in range(self.k):
                self.classes[i] = []

            # Find the distance between each point and the centroids
            for point in data:
                distances = []
                for index in self.centroids:
                    distances.append(self.distance(point, self.centroids[index]))

                # Assign the point to the nearest centroid
                cluster_index = distances.index(min(distances))
                self.classes[cluster_index].append(point)

            # Find the average of the points in each class to get the new centroids
            for index in self.classes:
                self.centroids[index] = np.average(self.classes[index], axis=0)

        return self.classes
```

