Here's an equivalent program in the C programming language that uses the Sieve of Eratosthenes algorithm to find prime numbers up to a given integer (in this case, 100):

```
#include <stdio.h>

int main() {
  int i, j, isprime[101];

  // initialize array to all ones
  for (i = 2; i <= 100; i++) {
    isprime[i] = 1;
  }

  // sieve of eratosthenes
  for (i = 2; i <= 100; i++) {
    if (isprime[i] == 1) {
      for (j = 2; j <= 100 / i; j++) {
        isprime[i*j] = 0;
      }
    }
  }

  // print out primes
  for (i = 2; i <= 100; i++) {
    if (isprime[i] == 1) {
      printf("%d\n", i);
    }
  }

  return 0;
}
```

